#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp_char(const void *a, const void *b) {
    return (*(const char *)a - *(const char *)b);
}

int main() {
    int n, m, k;
    if (scanf("%d %d %d", &n, &m, &k) != 3) return 0;

    char s[505];
    scanf("%s", s);

    char words[505][30];
    for (int i = 0; i < m; i++) {
        scanf("%s", words[i]);
        qsort(words[i], k, sizeof(char), cmp_char);
    }

    long long p;
    scanf("%lld", &p);
    p--; // converte para 0-indexado

    int choice[505];
    for (int i = m - 1; i >= 0; i--) {
        choice[i] = p % k;
        p /= k;
    }

    int word_idx = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == '#') {
            putchar(words[word_idx][choice[word_idx]]);
            word_idx++;
        } else {
            putchar(s[i]);
        }
    }
    putchar('\n');

    return 0;
}
